1	// Acceptance tests for the change request:
2	//   "Let me keep a task list on each project. Let me tick things off as I finish them."
3	//
4	// A project now keeps a list of tasks. Opening a project (project-open-<id> from the projects list)
5	// reaches its detail page, which lists THAT project's own tasks (project-tasks-table) — each row
6	// (task-row-<id>) showing the task's title (task-title) and a status (task-status) that reflects
7	// whether it is done. A project with no tasks shows an empty state (project-tasks-empty). Each task
8	// offers a control to tick it off / un-tick it (task-toggle-<id>); toggling flips THAT task's done
9	// status and appends one audit record — TASK_TOGGLED id=<id> done=<done> — so the change can be
10	// checked back later. Toggling one task must not touch its siblings, and each toggle writes its own
11	// record.
12	//
13	// Asserts ONLY through the two public channels: the UI (data-testid) and the audit file
14	// (auditLines()). Data is arranged via resetAndSeed; the toggle flow is driven through the UI.
15	// Seed honours tasks: { id, projectId, title, done }.
16	//
17	// The status LABEL text is not hard-coded (the request does not fix any wording): instead the test
18	// asserts that a done task's status DIFFERS from a not-done task's, and that toggling moves a task's
19	// status to match the done/not-done representation it should now have. The audit boolean is matched
20	// case-insensitively (done=true / done=false). This test SHOULD FAIL before the change: today a
21	// project's detail page has no task list at all.
22	import { test, expect } from '@playwright/test';
23	import { resetAndSeed } from '../support/seed';
24	import { auditLines } from '../support/audit';
25	
26	test.describe('project task list', () => {
27	  test('opening a project lists its own tasks with their titles, and a done task reads differently from a not-done one', async ({ page }) => {
28	    await resetAndSeed({
29	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
30	      projects: [
31	        { id: 1, clientId: 1, name: 'Website redesign' },
32	        { id: 2, clientId: 1, name: 'Warehouse automation' },
33	      ],
34	      tasks: [
35	        { id: 1, projectId: 1, title: 'Design the homepage', done: false },
36	        { id: 2, projectId: 1, title: 'Write the copy', done: true },
37	        // Belongs to a DIFFERENT project — it must not appear on project 1's page.
38	        { id: 3, projectId: 2, title: 'Install the conveyor', done: false },
39	      ],
40	    });
41	
42	    await page.goto('/projects');
43	    await page.getByTestId('project-open-1').click();
44	
45	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
46	    await expect(page.getByTestId('project-tasks-table')).toBeVisible();
47	    await expect(page.getByTestId('project-tasks-empty')).toHaveCount(0);
48	
49	    // Project 1's own tasks, each showing its title.
50	    const notDone = page.getByTestId('task-row-1');
51	    await expect(notDone).toBeVisible();
52	    await expect(notDone.getByTestId('task-title')).toHaveText('Design the homepage');
53	
54	    const done = page.getByTestId('task-row-2');
55	    await expect(done).toBeVisible();
56	    await expect(done.getByTestId('task-title')).toHaveText('Write the copy');
57	
58	    // The other project's task is not shown here.
59	    await expect(page.getByTestId('task-row-3')).toHaveCount(0);
60	
61	    // Each task surfaces a status, and the done task reads differently from the not-done one.
62	    await expect(notDone.getByTestId('task-status')).toBeVisible();
63	    await expect(done.getByTestId('task-status')).toBeVisible();
64	    const notDoneStatus = ((await notDone.getByTestId('task-status').textContent()) ?? '').trim();
65	    const doneStatus = ((await done.getByTestId('task-status').textContent()) ?? '').trim();
66	    expect(doneStatus).not.toBe(notDoneStatus);
67	  });
68	
69	  test('a project with no tasks shows an empty state and no task rows', async ({ page }) => {
70	    // The project exists so the page can only be empty of TASKS, not of everything.
71	    await resetAndSeed({
72	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
73	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
74	      tasks: [],
75	    });
76	
77	    await page.goto('/projects');
78	    await page.getByTestId('project-open-1').click();
79	
80	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
81	    await expect(page.getByTestId('project-tasks-empty')).toBeVisible();
82	    await expect(page.getByTestId('task-title')).toHaveCount(0);
83	  });
84	
85	  test('ticking a task off flips its status and keeps a record; toggling back flips it and records again', async ({ page }) => {
86	    await resetAndSeed({
87	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
88	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
89	      tasks: [
90	        { id: 1, projectId: 1, title: 'Ship the release', done: false },
91	        // A reference task seeded as DONE, so the test knows what a done status looks like without
92	        // hard-coding its wording.
93	        { id: 2, projectId: 1, title: 'Already finished', done: true },
94	      ],
95	    });
96	
97	    await page.goto('/projects');
98	    await page.getByTestId('project-open-1').click();
99	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
100	
101	    const row = page.getByTestId('task-row-1');
102	    await expect(row).toBeVisible();
103	
104	    const status = row.getByTestId('task-status');
105	    await expect(status).toBeVisible();
106	    const notDoneStatus = ((await status.textContent()) ?? '').trim();
107	    const doneStatus = ((await page.getByTestId('task-row-2').getByTestId('task-status').textContent()) ?? '').trim();
108	    // Done and not-done must look different, else "status" conveys nothing.
109	    expect(doneStatus).not.toBe(notDoneStatus);
110	
111	    // reset cleared the audit file — nothing has been toggled yet.
112	    expect(auditLines()).toEqual([]);
113	
114	    // Tick it off: its status moves to the done representation.
115	    await page.getByTestId('task-toggle-1').click();
116	    await expect(status).toHaveText(doneStatus);
117	
118	    // Exactly one record was kept for the toggle, naming the task and that it is now done.
119	    await expect
120	      .poll(() => auditLines().filter((l) => /^TASK_TOGGLED id=1 done=true$/i.test(l)))
121	      .toHaveLength(1);
122	    expect(auditLines()).toHaveLength(1);
123	
124	    // Toggle it back: its status returns to the not-done representation, and a second record is kept.
125	    await page.getByTestId('task-toggle-1').click();
126	    await expect(status).toHaveText(notDoneStatus);
127	
128	    await expect.poll(() => auditLines()).toHaveLength(2);
129	    const lines = auditLines();
130	    expect(lines.some((l) => /^TASK_TOGGLED id=1 done=true$/i.test(l))).toBe(true);
131	    expect(lines.some((l) => /^TASK_TOGGLED id=1 done=false$/i.test(l))).toBe(true);
132	  });
133	
134	  test('toggling one task leaves its siblings untouched, and each toggle writes its own record', async ({ page }) => {
135	    await resetAndSeed({
136	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
137	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
138	      tasks: [
139	        { id: 1, projectId: 1, title: 'First task', done: false },
140	        { id: 2, projectId: 1, title: 'Second task', done: false },
141	      ],
142	    });
143	
144	    await page.goto('/projects');
145	    await page.getByTestId('project-open-1').click();
