1	// Acceptance tests for the change request:
2	//   "Let me change or remove those charge lines on an invoice. Update the total when I do."
3	//
4	// An invoice is already built up from the things being charged for — line items shown on the invoice
5	// detail page (invoice-detail-page) in the line-items table (invoice-lineitems-table), each row
6	// (lineitem-row-<id>) carrying a description, how many, the price each, and the worked-out line
7	// amount. This change lets the user take a charge line OFF an invoice: each row gains a remove
8	// control (lineitem-remove-<id>). The point — "update the total when I do" — is that the invoice's
9	// amount is still the SUM worked out from whatever lines REMAIN, never a stored figure; so removing a
10	// line must drop that line's amount out of the total everywhere the total is surfaced: the detail
11	// page's own total (invoice-amount, in the table footer) and the all-invoices list row
12	// (invoice-amount).
13	//
14	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed, which honours invoices
15	// with a `lineItems` array of { id, description, qty, unitPrice }. No `amount` is seeded: the total
16	// must be worked out from the lines, so the removal is proven by the total CHANGING to the sum of the
17	// survivors. This test must FAIL before the change: there is no remove control today.
18	//
19	// The detail page is reached by navigating to its own route (/invoices/<id>) — a URL, the same public
20	// surface the specs already use with page.goto. Line amounts are chosen so none is a substring of
21	// another or of either total (300 / 100 / 200, totals 600 then 500), and every per-row/per-line
22	// assertion is scoped to its row so a stray match cannot pass by accident. Totals are money and
23	// asserted exactly ("$500.00"); the lenient lineitem cells follow the existing invoice-lineitems spec.
24	import { test, expect } from '@playwright/test';
25	import { resetAndSeed } from '../support/seed';
26	
27	test.describe('charge lines can be removed from an invoice, and the total follows', () => {
28	  test('removing one line drops only that line, keeps the rest, and re-works the total', async ({ page }) => {
29	    await resetAndSeed({
30	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
31	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
32	      invoices: [
33	        {
34	          id: 1,
35	          projectId: 1,
36	          status: 'DRAFT',
37	          // Three things being charged for. No `amount`: the total is worked out from these.
38	          lineItems: [
39	            { id: 1, description: 'Design work', qty: 2, unitPrice: 150 }, // 2 * 150 = 300
40	            { id: 2, description: 'Hosting setup', qty: 4, unitPrice: 25 }, // 4 * 25  = 100
41	            { id: 3, description: 'Copywriting', qty: 5, unitPrice: 40 }, // 5 * 40  = 200
42	          ],
43	        },
44	      ],
45	    });
46	
47	    // Before removing anything: the all-invoices list shows the full worked-out total (300+100+200).
48	    await page.goto('/invoices');
49	    await expect(page.getByTestId('invoices-page')).toBeVisible();
50	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$600.00');
51	
52	    // Open the invoice's own detail page to see its lines.
53	    await page.goto('/invoices/1');
54	    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
55	    await expect(page.getByTestId('invoice-lineitems-table')).toBeVisible();
56	
57	    // All three lines are present, and the detail page's own total (table footer) is the full sum.
58	    await expect(page.getByTestId('lineitem-row-1')).toBeVisible();
59	    await expect(page.getByTestId('lineitem-row-2')).toBeVisible();
60	    await expect(page.getByTestId('lineitem-row-3')).toBeVisible();
61	    const detailTotal = page.getByTestId('invoice-detail-page').getByTestId('invoice-amount');
62	    await expect(detailTotal).toHaveText('$600.00');
63	
64	    // Take the middle line ("Hosting setup", $100) off the invoice.
65	    await page.getByTestId('lineitem-remove-2').click();
66	
67	    // That line is gone; the other two remain exactly as they were.
68	    await expect(page.getByTestId('lineitem-row-2')).toHaveCount(0);
69	    const first = page.getByTestId('lineitem-row-1');
70	    await expect(first).toBeVisible();
71	    await expect(first.getByTestId('lineitem-description')).toHaveText('Design work');
72	    await expect(first.getByTestId('lineitem-amount')).toHaveText(/^\$?300(\.00)?$/);
73	    const third = page.getByTestId('lineitem-row-3');
74	    await expect(third).toBeVisible();
75	    await expect(third.getByTestId('lineitem-description')).toHaveText('Copywriting');
76	    await expect(third.getByTestId('lineitem-amount')).toHaveText(/^\$?200(\.00)?$/);
77	
78	    // The total is re-worked from the survivors (300 + 200), on the detail page...
79	    await expect(detailTotal).toHaveText('$500.00');
