107	    await expect(row).toBeVisible();
108	    await expect(page.getByTestId('invoice-detail-page').getByTestId('invoice-amount')).toHaveText('$270.00');
109	
110	    // Remove the only charge line.
111	    await page.getByTestId('lineitem-remove-1').click();
112	
113	    // No rows remain, but the region is still there (ready for a new line) and the total is zero.
114	    await expect(page.getByTestId('lineitem-row-1')).toHaveCount(0);
115	    await expect(page.getByTestId('lineitem-description')).toHaveCount(0);
116	    await expect(page.getByTestId('invoice-lineitems-table')).toBeVisible();
117	    await expect(page.getByTestId('invoice-detail-page').getByTestId('invoice-amount')).toHaveText('$0.00');
118	
119	    // The all-invoices list reflects the now-empty invoice too.
120	    await page.goto('/invoices');
121	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-amount')).toHaveText('$0.00');
122	  });
123	});
